def transform(grid):
 h,w=len(grid),len(grid[0]); color=next(v for row in grid for v in row if v not in (0,4)); pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts); shape={(r-r0,c-c0) for r,c in pts}; hh=max(r for r,c in shape)+1; ww=max(c for r,c in shape)+1
 out=[row[:] for row in grid]
 for a in range(h-hh+1):
  for b in range(w-ww+1):
   if (a,b)==(r0,c0): continue
   if all(grid[a+r][b+c]==0 for r,c in shape):
    for r,c in shape: out[a+r][b+c]=color
 return out
